CREATE TABLE IF NOT EXISTS "Drivers" (
    id SERIAL PRIMARY KEY,
    "Manufacturer" TEXT,
    "Release Year" TEXT,
    "Model Name" TEXT,
    "Category" TEXT,
    "CC" TEXT,
    "Standard Loft" TEXT,
    "Face Material" TEXT,
    "Adjustability" TEXT,
    "Weight System" TEXT,
    "Weight Range" TEXT,
    "Cost (MSRP)" TEXT,
    "Stock Length" TEXT,
    "Swing Weight" TEXT,
    "Target Player Profile" TEXT,
    "Spin Profile" TEXT,
    "Bias" TEXT,
    "Offset" TEXT,
    "Left Handed" TEXT
);

ALTER TABLE "Drivers" ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Public Select" ON "Drivers";
CREATE POLICY "Public Select" ON "Drivers" FOR SELECT USING (true);

TRUNCATE TABLE "Drivers";



